svg.script:
const MARGIN=14, GRAPH_WIDTH=1772;
function fit(g){const r=g.querySelector("rect"),t=g.querySelector("text"),full=g.dataset.name;const w=parseFloat(r.getAttribute("width"));t.setAttribute("x",parseFloat(r.getAttribute("x"))+4);if(w<10){t.textContent="";return;}const n=Math.max(0,Math.floor((w-7)/6.5));t.textContent=full.length>n?full.slice(0,Math.max(0,n-2))+"…":full;}
function zoom(evt,target){evt.stopPropagation();const tx=parseFloat(target.dataset.x),tw=parseFloat(target.dataset.w),tp=target.dataset.path;if(tw<=0)return;const scale=GRAPH_WIDTH/tw;document.querySelectorAll("g.frame").forEach(g=>{const p=g.dataset.path;const descendant=(p===tp||p.startsWith(tp+"/"));if(!descendant){g.style.display="none";return;}g.style.display="";const x=MARGIN+(parseFloat(g.dataset.x)-tx)*scale;const w=parseFloat(g.dataset.w)*scale;g.querySelector("rect").setAttribute("x",x);g.querySelector("rect").setAttribute("width",w);fit(g);});document.getElementById("status").textContent="已放大: "+target.dataset.name;}
function resetZoom(evt){if(evt)evt.stopPropagation();document.querySelectorAll("g.frame").forEach(g=>{g.style.display="";g.querySelector("rect").setAttribute("x",g.dataset.x);g.querySelector("rect").setAttribute("width",g.dataset.w);fit(g);});document.getElementById("status").textContent="";}
function searchFrames(evt){evt.stopPropagation();const q=prompt("输入函数名（不区分大小写）:");if(q===null)return;const s=q.toLowerCase();let n=0;document.querySelectorAll("g.frame").forEach(g=>{const hit=s&&g.dataset.name.toLowerCase().includes(s);g.querySelector("rect").style.stroke=hit?"#e60000":"#fff";g.querySelector("rect").style.strokeWidth=hit?"2.5":".45";if(hit)n++;});document.getElementById("status").textContent=s?"匹配 "+n+" 个 frame: "+q:"";}
window.addEventListener("load",()=>document.querySelectorAll("g.frame").forEach(fit));
